  "name": "w10n-example",
  "version": "0.0.1",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "npm run tsc && vite build",
    "tsc": "tsc --noEmit"
  },
  "devDependencies": {
    "@crxjs/vite-plugin": "^2.7.1",
    "@types/chrome": "^0.2.8",
    "@types/node": "^22.0.0",
    "typescript": "^6.0.3",
    "vite": "^7.3.6",
    "vite-plugin-zip-pack": "^1.2.4"
  }
}

/**
 * Configures JavaScript and TypeScript linting with the repository's Git ignores.
 */
import js from '@eslint/js';
import { defineConfig, includeIgnoreFile } from 'eslint/config';
import visualComplexity from 'eslint-plugin-visual-complexity';
import globals from 'globals';
import { fileURLToPath } from 'node:url';
import tseslint from 'typescript-eslint';

export default defineConfig(
  includeIgnoreFile(
    [
      fileURLToPath(new URL('.gitignore', import.meta.url)),
      fileURLToPath(new URL('example/.gitignore', import.meta.url)),
    ],
    { gitignoreResolution: true },
  ),
  {
    files: ['**/*.{js,mjs,ts}'],
    extends: [js.configs.recommended],
    plugins: {
      visual: visualComplexity,
    },
    rules: {
      complexity: 0,
      'visual/complexity': ['error', { max: 5 }],
      'max-depth': ['error', { max: 2 }],
      'max-nested-callbacks': ['error', { max: 2 }],
      'max-params': ['error', { max: 3 }],
      'max-statements': ['error', { max: 12 }, { ignoreTopLevelFunctions: false }],
      'max-lines-per-function': ['error', { max: 30, skipBlankLines: true, skipComments: true }],
      'max-len': ['error', { code: 120, ignoreUrls: true }],
      'max-lines': ['error', { max: 200, skipComments: true, skipBlankLines: true }],
    },
  },
  {
    files: ['**/*.ts'],
    extends: [tseslint.configs.recommended],
  },
  {
    files: ['**/*.{js,mjs}'],
    languageOptions: { globals: globals.node },
  },
  {
    files: ['src/google-analytics/index.ts', 'example/src/w10n/google-analytics/index.ts'],
    rules: {
      // EventArguments uses {} to check whether event parameters are optional.
      '@typescript-eslint/no-empty-object-type': ['error', { allowObjectTypes: 'always' }],
    },
  },
);

/**
 * Builds and packages the extension with CRXJS and enables example logging by default.
 */
import { crx } from '@crxjs/vite-plugin';
import { defineConfig } from 'vite';
import zip from 'vite-plugin-zip-pack';
import manifest from './manifest.config';

export default defineConfig(({ command }) => ({
  plugins: [
    crx({ manifest }),
    zip({ inDir: 'dist/prod', outDir: 'dist', outFileName: 'prod.zip' }),
  ],
  build: { outDir: command === 'serve' ? 'dist/dev' : 'dist/prod' },
  define: { 'import.meta.env.LOGGING': JSON.stringify('true') },
}));

